#!/bin/sh
# 由 vuna 生成：分离编译构建脚本。用法: ./build.sh [OUT]
# 干净构建：一次 ocamlopt 编译全部 .mli/.ml 并链接；
# 增量构建：按 .ml/.mli/.cmi 时间戳逐模块重编（编译单元顺序即依赖顺序）。
set -eu
cd "$(dirname "$0")"
OUT=${1:-program}
FLAGS="-g -w -a+39 -warn-error +39"
MODULES="Vuna_runtime Base_dPair Base_dBool Base_dMonad Base_dMaybe Base_dList Base_dIO Base_dResult Base_dString Prelude Vuna_dCompiler_dCommon Vuna_dCompiler_dToml Vuna_dCompiler_dManifest Vuna_dCompiler_dPkg Vuna_dCompiler_dAst Vuna_dCompiler_dLexer Vuna_dCompiler_dParser Vuna_dCompiler_dBuiltins Vuna_dCompiler_dLoader Vuna_dCompiler_dTypecheck Vuna_dCompiler_dSplit Vuna_dCompiler_dTypedCodegen Vuna_dCompiler_dCore Vuna_dCompiler_dDtPrelude Vuna_dCompiler_dDtKind Vuna_dCompiler_dDtQuant Vuna_dCompiler_dDtDerive Vuna_dCompiler_dDtRecords Vuna_dCompiler_dElab Vuna_dCompiler_dCoreCodegen Vuna_dCompiler_dDt Vuna_dCompiler_dCompile Vuna_dCompiler_dSplitCli Vuna_dCompiler_dProcess Vuna_dCompiler_dCompilerCli Main "
clean=1
for m in $MODULES; do
  if [ -f "$m.cmx" ]; then clean=0; fi
done
if [ "$clean" -eq 1 ]; then
  SOURCES=""
  for m in $MODULES; do
    if [ -f "$m.mli" ]; then SOURCES="$SOURCES $m.mli"; fi
    SOURCES="$SOURCES $m.ml"
  done
  ocamlopt $FLAGS -I +unix -o "$OUT" unix.cmxa $SOURCES
  echo "built $OUT"
  exit 0
fi
compile_mod() {
  base=$1
  shift
  stale=0
  [ -f "$base.cmx" ] || stale=1
  if [ "$stale" -eq 0 ] && [ "$base.ml" -nt "$base.cmx" ]; then stale=1; fi
  if [ -f "$base.mli" ]; then
    [ -f "$base.cmi" ] || stale=1
    if [ "$stale" -eq 0 ] && [ "$base.mli" -nt "$base.cmi" ]; then stale=1; fi
  fi
  for dep in "$@"; do
    if [ "$stale" -eq 0 ] && [ -f "$dep.cmi" ] && [ "$dep.cmi" -nt "$base.cmx" ]; then stale=1; fi
    if [ "$stale" -eq 1 ]; then break; fi
  done
  if [ "$stale" -eq 1 ]; then
    echo "compile $base"
    if [ -f "$base.mli" ]; then ocamlopt $FLAGS -I +unix -c "$base.mli"; fi
    ocamlopt $FLAGS -I +unix -c "$base.ml"
  fi
}
